function draw(){const cw=canvas.width,ch=canvas.height,scale=Math.min(cw/780,ch/520),camX=Math.max(0,Math.min(W-cw/scale,player.x-cw/scale/2)),camY=Math.max(0,Math.min(H-ch/scale,player.y-ch/scale/2));ctx.fillStyle='#061116';ctx.fillRect(0,0,cw,ch);ctx.save();ctx.scale(scale,scale);ctx.translate(-camX,-camY);
 let x0=Math.floor(camX/TILE),y0=Math.floor(camY/TILE),x1=Math.min(COLS,Math.ceil((camX+cw/scale)/TILE)+1),y1=Math.min(ROWS,Math.ceil((camY+ch/scale)/TILE)+1);let current=roomAt(player.x,player.y),visRadius=player.hidden?140:profile.upgrades.scanner?350:280;
 for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){let t=world.tiles[idx(x,y)],px=x*TILE,py=y*TILE,rm=world.rooms[Math.max(0,Math.min(ROOM_R-1,Math.floor((y-ROOM_Y)/7)))*ROOM_C+Math.max(0,Math.min(ROOM_C-1,Math.floor((x-ROOM_X)/9)))],known=visited.has(rm.ry*ROOM_C+rm.rx)||Math.hypot((px+16)-player.x,(py+16)-player.y)<visRadius;if(!known){ctx.fillStyle='#050d11';ctx.fillRect(px,py,TILE,TILE);continue}if(t===0){ctx.fillStyle='#091419';ctx.fillRect(px,py,TILE,TILE);continue}if(t===2){ctx.fillStyle='#19292c';ctx.fillRect(px,py,TILE,TILE);ctx.fillStyle='#2d4548';ctx.fillRect(px,py,32,3);ctx.fillStyle='#111f23';ctx.fillRect(px+4,py+5,24,2);continue}ctx.fillStyle=rm.type===0?'#14272b':rm.type===1?'#182628':rm.type===2?'#11232c':rm.type===3?'#1a2424':'#202324';ctx.fillRect(px,py,TILE,TILE);ctx.strokeStyle='#20363a';ctx.lineWidth=1;ctx.strokeRect(px+.5,py+.5,31,31);if(t===3){ctx.fillStyle='#334447';ctx.fillRect(px+4,py+5,24,21);ctx.fillStyle='#607375';ctx.fillRect(px+6,py+5,20,3);ctx.fillStyle='#0b1518';ctx.fillRect(px+9,py+11,14,9)}if(t===4){let h=hazards.find(h=>Math.floor(h.x/TILE)===x&&Math.floor(h.y/TILE)===y);ctx.fillStyle=h?.type==='electric'?'#23413d':'#422e28';ctx.fillRect(px+2,py+2,28,28);if(h?.type==='electric'&&Math.sin(gameTime*3+h.phase)>.1){ctx.strokeStyle='#6bf5ce';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(px+9,py+7);ctx.lineTo(px+19,py+15);ctx.lineTo(px+12,py+22);ctx.lineTo(px+25,py+27);ctx.stroke()}else if(h){ctx.strokeStyle='#95654a';ctx.beginPath();ctx.moveTo(px+8,py+7);ctx.lineTo(px+14,py+15);ctx.lineTo(px+9,py+25);ctx.moveTo(px+14,py+15);ctx.lineTo(px+25,py+9);ctx.stroke()}}
 // room fixtures: screen consoles and warning strobes
 for(const room of world.rooms){if(!visited.has(room.ry*ROOM_C+room.rx)&&Math.hypot((room.x+4.5)*TILE-player.x,(room.y+3.5)*TILE-player.y)>visRadius)continue;let rx=room.x*TILE,ry=room.y*TILE;if(room.type===0||room.type===2){ctx.fillStyle=room.type===0?'#1b3437':'#162d38';ctx.fillRect(rx+38,ry+38,45,11);ctx.fillStyle=room.type===0?'#44bea6':'#3aa8cf';ctx.fillRect(rx+42,ry+41,37,5);ctx.fillStyle='#637f7b';ctx.fillRect(rx+44,ry+49,3,8);ctx.fillRect(rx+75,ry+49,3,8)}if((room.rx+room.ry)%3===0){ctx.fillStyle=Math.sin(gameTime*2+room.rx)>.15?'#ee8153':'#553b30';ctx.beginPath();ctx.arc(rx+16,ry+16,2.4,0,Math.PI*2);ctx.fill()}}
 // exit elevator
 let ex=world.exit.x,ey=world.exit.y;ctx.fillStyle='#263a3a';ctx.fillRect(ex-24,ey-23,48,46);ctx.strokeStyle='#ff9954';ctx.lineWidth=2;ctx.strokeRect(ex-21,ey-20,42,40);ctx.fillStyle='#163332';ctx.fillRect(ex-14,ey-14,28,28);ctx.fillStyle='#74e6c0';ctx.fillRect(ex-9,ey-10,18,3);ctx.fillStyle='#244e49';ctx.fillRect(ex-9,ey-3,18,14);ctx.fillStyle='#ff9d59';ctx.beginPath();ctx.arc(ex+17,ey-16,3,0,Math.PI*2);ctx.fill();ctx.font='8px monospace';ctx.fillStyle='#b9cec7';ctx.textAlign='center';ctx.fillText('EXTRACT',ex,ey+34);
 // caches
 for(const l of loot){if(l.opened||Math.hypot(l.x-player.x,l.y-player.y)>visRadius+80)continue;ctx.fillStyle='#33433e';ctx.fillRect(l.x-9,l.y-8,18,16);ctx.fillStyle='#718277';ctx.fillRect(l.x-9,l.y-8,18,3);ctx.fillStyle=rarity[l.item.rarity][1];ctx.fillRect(l.x-3,l.y-2,6,6);if(Math.hypot(l.x-player.x,l.y-player.y)<50){ctx.font='9px monospace';ctx.fillStyle='#d3e2d9';ctx.textAlign='center';ctx.fillText('E  SEARCH',l.x,l.y-16)}}
 // drones and glow
 for(const b of drones){let dist=Math.hypot(player.x-b.x,player.y-b.y);if(dist>visRadius+110)continue;ctx.save();ctx.globalAlpha=.12+b.alert*.15;ctx.fillStyle=b.alert>.2?'#ff604c':'#df594c';ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.arc(b.x,b.y,100,-.5,.5);ctx.closePath();ctx.fill();ctx.restore();ctx.fillStyle='#3c4849';ctx.beginPath();ctx.arc(b.x,b.y,11,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#9b6b5c';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle=b.alert>.2?'#ff735a':'#f3a761';ctx.beginPath();ctx.arc(b.x+2,b.y,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b8c2b9';ctx.fillRect(b.x-15,b.y-2,5,4);ctx.fillRect(b.x+10,b.y-2,5,4)}
 // player shadow, suit, smooth directional bob
 let bob=Math.sin(player.step)*1.3,px=player.x,py=player.y+bob;ctx.fillStyle='#03070888';ctx.beginPath();ctx.ellipse(px,py+8,10,5,0,0,Math.PI*2);ctx.fill();ctx.save();if(player.invuln>0&&Math.floor(gameTime*15)%2)ctx.globalAlpha=.45;ctx.fillStyle=player.hidden?'#61756e':'#c6ded2';ctx.beginPath();ctx.arc(px,py,9,0,Math.PI*2);ctx.fill();ctx.fillStyle=player.hidden?'#2a6057':'#368e7e';ctx.fillRect(px-6,py-5,12,10);ctx.fillStyle='#9bf1d6';ctx.fillRect(px-3,py-3,7,3);ctx.fillStyle='#152629';ctx.fillRect(px-2,py+4,5,3);ctx.restore();if(player.hidden){ctx.strokeStyle='#6ce2bd77';ctx.beginPath();ctx.arc(px,py,17+Math.sin(gameTime*3)*2,0,Math.PI*2);ctx.stroke()}
 // darkness vignette
 const g=ctx.createRadialGradient(player.x,player.y,50,player.x,player.y,visRadius);g.addColorStop(0,'#00000000');g.addColorStop(.72,'#02080a16');g.addColorStop(1,'#02080ad9');ctx.fillStyle=g;ctx.fillRect(camX,camY,cw/scale,ch/scale);
 ctx.restore();if(damageFlash>0){ctx.fillStyle=`rgba(255,60,45,${damageFlash*.35})`;ctx.fillRect(0,0,cw,ch)}drawMap();
}
function drawMap(){let w=mapCanvas.width,h=mapCanvas.height;mctx.fillStyle='#071216';mctx.fillRect(0,0,w,h);for(const rm of world.rooms){let x=10+rm.rx*42,y=8+rm.ry*25,seen=visited.has(rm.ry*ROOM_C+rm.rx);if(!seen){mctx.fillStyle='#101d21'}else{mctx.fillStyle=['#243b3a','#293735','#1c3540','#303633','#34332e'][rm.type]}mctx.fillRect(x,y,35,18);if(seen){mctx.strokeStyle='#385251';mctx.strokeRect(x+.5,y+.5,34,17);for(const d of Object.keys(rm.doors)){mctx.fillStyle='#516a62';if(d==='right')mctx.fillRect(x+34,y+8,5,2);if(d==='left')mctx.fillRect(x-4,y+8,5,2);if(d==='down')mctx.fillRect(x+17,y+17,2,5);if(d==='up')mctx.fillRect(x+17,y-4,2,5)}}}let ex=world.exit;mctx.fillStyle='#ff9954';mctx.fillRect(10+4*42+17,8+3*25+7,4,4);mctx.fillStyle='#57ecc8';let pr=roomAt(player.x,player.y);mctx.fillRect(10+pr.rx*42+16,8+pr.ry*25+6,6,6);mctx.strokeStyle='#57ecc8';mctx.strokeRect(10+pr.rx*42+13,8+pr.ry*25+3,12,12)}
function renderUI(){document.getElementById('credits').textContent=String(profile.credits).padStart(3,'0');document.getElementById('healthFill').style.width=player.hp+'%';document.getElementById('healthValue').textContent=Math.ceil(player.hp);let bp=Math.max(0,player.battery/capBattery()*100);document.getElementById('batteryFill').style.width=bp+'%';document.getElementById('batteryValue').textContent=Math.ceil(player.battery);document.getElementById('packCount').textContent=`${String(player.bag.length).padStart(2,'0')} / ${String(packMax()).padStart(2,'0')}`;document.getElementById('levelText').textContent=`LV ${String(1+Math.floor(profile.secured/4)).padStart(2,'0')}`;document.getElementById('inventory').innerHTML=Array.from({length:packMax()},(_,n)=>{let item=player.bag[n];return item?`<div class="slot" title="${item.name} · ${rarity[item.rarity][0]}" style="border-color:${rarity[item.rarity][1]}">${item.icon}<em>${n+1}</em></div>`:'<div class="slot empty">·</div>'}).join('');document.getElementById('lootLine').textContent=player.bag.length?player.bag.map(i=>i.name).join(' · '):'No recovered items. Search nearby containers.';let nearExit=Math.hypot(player.x-world.exit.x,player.y-world.exit.y)<150;document.getElementById('zoneTag').textContent=nearExit?'ELEVATOR SIGNAL · NEAR':'SIGNAL TRACE: ACTIVE';document.getElementById('status').textContent=player.hidden?'SIGNATURE MASKED':nearExit?'EXTRACTION IN RANGE':drones.some(b=>Math.hypot(b.x-player.x,b.y-player.y)<160&&b.alert>.1)?'HOSTILE CONTACT':'LINK STABLE';document.getElementById('canvasHint').innerHTML=nearExit?'<span style="color:#ffb16e">E</span> EXTRACT <span style="color:#456469">·</span> SECURE YOUR RECOVERABLES':'WASD MOVE <span style="color:#456469">·</span> E SEARCH <span style="color:#456469">·</span> H HIDE';}

const upgrades=[{id:'scanner',name:'SIGNAL AMPLIFIER',desc:'Widen your scan radius and reveal caches from farther away.',cost:[90,180,320],icon:'⌕'},{id:'battery',name:'CAPACITOR ARRAY',desc:'Increase cell capacity by 25 units per upgrade.',cost:[80,160,280],icon:'ϟ'},{id:'pack',name:'EXPANDED FIELD PACK',desc:'Carry two additional recovered items.',cost:[110,220],icon:'▦'},{id:'speed',name:'SERVO TUNING',desc:'Increase movement speed; sprint drains more cell.',cost:[100,200,350],icon:'»'},{id:'access',name:'RESTRICTED ACCESS',desc:'Unlock deeper research sector routes and better caches.',cost:[280],icon:'⌑'}];
function openBase(){paused=true;const grid=document.getElementById('upgradeGrid');grid.innerHTML=upgrades.map(u=>{let level=profile.upgrades[u.id],cost=u.cost[level],done=cost===undefined;return `<div class="upgrade"><h3>${u.icon} &nbsp;${u.name} <span style="color:#6b9595">${level?`LV ${level}`:''}</span></h3><p>${u.desc}${done?'<br><span style="color:#64d5af">SYSTEM MAXED</span>':''}</p><button class="ui-btn ${done?'':'primary'}" data-upgrade="${u.id}" ${done||profile.credits<cost?'disabled':''}>${done?'INSTALLED':`INSTALL · ${cost} CR`}</button></div>`}).join('');document.getElementById('modalCredits').textContent=profile.credits+' CR';document.getElementById('securedCount').textContent=profile.secured;document.getElementById('baseOverlay').classList.add('open')}
document.getElementById('upgradeGrid').addEventListener('click',e=>{let id=e.target.dataset.upgrade;if(!id)return;let u=upgrades.find(a=>a.id===id),cost=u.cost[profile.upgrades[id]];if(cost===undefined||profile.credits<cost)return;profile.credits-=cost;profile.upgrades[id]++;if(id==='battery'&&player)player.battery=Math.min(capBattery(),player.battery+25);save();openBase();renderUI();toast(`${u.name} INSTALLED`) });
document.getElementById('baseBtn').addEventListener('click',openBase);document.getElementById('restartBtn').addEventListener('click',()=>{if(runOver){closeOverlay('resultOverlay');generate();renderUI();return}if(confirm('Abandon this mission? Unextracted items will be lost.')){finish(false)}});
document.getElementById('continueBtn').addEventListener('click',()=>{closeOverlay('resultOverlay');generate();renderUI()});function closeOverlay(id){document.getElementById(id).classList.remove('open');paused=false}document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>closeOverlay(b.dataset.close)));
window.addEventListener('keydown',e=>{let code=e.code;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(code))e.preventDefault();keys[code]=true;if(e.repeat)return;if(code==='KeyE'||code==='Space')interact();if(code==='KeyH')toggleHide();if(code==='Escape'){if(document.getElementById('baseOverlay').classList.contains('open'))closeOverlay('baseOverlay');else if(document.getElementById('resultOverlay').classList.contains('open'))closeOverlay('resultOverlay')}});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{keys={};joystick.x=joystick.y=0});
function setupJoystick(){const joy=document.getElementById('joy'),knob=document.getElementById('joyKnob');function update(e){let rect=joy.getBoundingClientRect(),dx=e.clientX-(rect.left+rect.width/2),dy=e.clientY-(rect.top+rect.height/2),max=35,l=Math.hypot(dx,dy);if(l>max){dx=dx/l*max;dy=dy/l*max}joystick.x=dx/max;joystick.y=dy/max;knob.style.transform=`translate(${dx}px,${dy}px)`}joy.addEventListener('pointerdown',e=>{joystick.active=true;joy.setPointerCapture(e.pointerId);update(e)});joy.addEventListener('pointermove',e=>{if(joystick.active)update(e)});const end=()=>{joystick.active=false;joystick.x=joystick.y=0;knob.style.transform=''};joy.addEventListener('pointerup',end);joy.addEventListener('pointercancel',end)}setupJoystick();document.getElementById('touchUse').addEventListener('pointerdown',e=>{e.preventDefault();interact()});document.getElementById('touchHide').addEventListener('pointerdown',e=>{e.preventDefault();toggleHide()});
function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,1.5);canvas.width=Math.max(1,Math.floor(rect.width*dpr));canvas.height=Math.max(1,Math.floor(rect.height*dpr));ctx.imageSmoothingEnabled=false}window.addEventListener('resize',resize);
function frame(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;gameTime+=dt;if(!paused){move(dt);renderUI()}draw();requestAnimationFrame(frame)}
generate();resize();renderUI();requestAnimationFrame(frame);
})();
</script></body></html>

