const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),mapCanvas=document.getElementById('map'),mctx=mapCanvas.getContext('2d');
const TILE=32,COLS=49,ROWS=35,ROOM_W=9,ROOM_H=7,ROOM_X=3,ROOM_Y=3,ROOM_C=5,ROOM_R=4,saveKey='lostSignalDeepRecovery_v1';
const defaults={credits:0,secured:0,upgrades:{scanner:0,battery:0,pack:0,speed:0,access:0},runs:0};let profile=loadProfile(),world,player,loot,drones,hazards,visited,keys={},last=0,gameTime=0,paused=false,runOver=false,missionSeed=0,toastTimer,damageFlash=0,joystick={x:0,y:0,active:false};
const rarity=[['COMMON','#b6c8c1'],['UNCOMMON','#71ddb0'],['RARE','#76beff'],['LEGENDARY','#ffd179']],itemPool=[{name:'Optic relay',icon:'◈',rarity:0,value:32},{name:'Bio-key sample',icon:'⌬',rarity:0,value:38},{name:'Power cell',icon:'ϟ',rarity:1,value:46,cell:true},{name:'Research drive',icon:'▣',rarity:1,value:56},{name:'Quantum lens',icon:'◇',rarity:2,value:92},{name:'Prototype core',icon:'✧',rarity:3,value:180},{name:'Encrypted dossier',icon:'▤',rarity:2,value:105},{name:'Cryo artifact',icon:'❖',rarity:3,value:210}];
function loadProfile(){try{let p=JSON.parse(localStorage.getItem(saveKey))||{};return {...defaults,...p,upgrades:{...defaults.upgrades,...p.upgrades}}}catch(e){return JSON.parse(JSON.stringify(defaults))}}function save(){try{localStorage.setItem(saveKey,JSON.stringify(profile))}catch(e){}}const capBattery=()=>100+profile.upgrades.battery*25,packMax=()=>6+profile.upgrades.pack*2,speedNow=()=>168+profile.upgrades.speed*16;
function rng(seed){let s=seed>>>0;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296}}const idx=(x,y)=>y*COLS+x;
function generate(){missionSeed=(Date.now()^Math.floor(Math.random()*1e9))>>>0;const r=rng(missionSeed),tiles=new Uint8Array(COLS*ROWS),rooms=[];
 for(let ry=0;ry<ROOM_R;ry++)for(let rx=0;rx<ROOM_C;rx++){let x=3+rx*9,y=3+ry*7;let room={rx,ry,x,y,type:(rx*3+ry*2+Math.floor(r()*5))%5,doors:{}};rooms.push(room);for(let yy=y;yy<y+ROOM_H;yy++)for(let xx=x;xx<x+ROOM_W;xx++)tiles[idx(xx,yy)]=1;for(let xx=x;xx<x+ROOM_W;xx++){tiles[idx(xx,y)]=2;tiles[idx(xx,y+ROOM_H-1)]=2}for(let yy=y;yy<y+ROOM_H;yy++){tiles[idx(x,yy)]=2;tiles[idx(x+ROOM_W-1,yy)]=2}}
