  else if(t===4){let hz=hazards.find(v=>Math.floor(v.x/TILE)===x&&Math.floor(v.y/TILE)===y);ctx.fillStyle=hz?.type==='electric'?'#153b3a':'#352c26';ctx.fillRect(sx+3,sy+3,TILE-6,TILE-6);ctx.strokeStyle=hz?.type==='electric'?'#4de2c1':'#d18b4e';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(sx+8,sy+23);ctx.lineTo(sx+15,sy+9);ctx.lineTo(sx+20,sy+20);ctx.lineTo(sx+25,sy+8);ctx.stroke();ctx.lineWidth=1}
 }
 // exit beacon
