 for(const l of loot)if(!l.opened){let x=l.x-camX,y=l.y-camY;if(x<-20||y<-20||x>w+20||y>h+20)continue;ctx.fillStyle=['#aebdb6','#71ddb0','#76beff','#ffd179'][l.item.rarity];ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=10;ctx.fillRect(x-7,y-7,14,14);ctx.shadowBlur=0;ctx.strokeStyle='#061116';ctx.strokeRect(x-4,y-4,8,8)}
 for(const b of drones){let x=b.x-camX,y=b.y-camY;ctx.fillStyle=b.alert>.25?'#ff785f':'#e17d54';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=12;ctx.beginPath();ctx.arc(x,y,9,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#ffd0a2';ctx.beginPath();ctx.moveTo(x-13,y);ctx.lineTo(x+13,y);ctx.moveTo(x,y-13);ctx.lineTo(x,y+13);ctx.stroke();if(b.alert>.3){ctx.strokeStyle='#ff765d77';ctx.beginPath();ctx.arc(x,y,16,0,Math.PI*2);ctx.stroke()}}
