function drawMap(){const w=mapCanvas.width,h=mapCanvas.height;mctx.clearRect(0,0,w,h);mctx.fillStyle='#071216';mctx.fillRect(0,0,w,h);const sx=w/(COLS*TILE),sy=h/(ROWS*TILE);for(let n=0;n<world.rooms.length;n++){if(!visited.has(n))continue;let r=world.rooms[n];mctx.fillStyle='#254148';mctx.fillRect(r.x*TILE*sx,r.y*TILE*sy,ROOM_W*TILE*sx,ROOM_H*TILE*sy);for(const d of Object.values(r.doors)){if(d!==undefined){mctx.fillStyle='#31575a';if(d>30)mctx.fillRect((r.x+8)*TILE*sx,d*TILE*sy,3,3);}}}for(const l of loot)if(!l.opened){mctx.fillStyle='#9acbba';mctx.fillRect(l.x*sx-1,l.y*sy-1,3,3)}mctx.fillStyle='#ff9b55';mctx.beginPath();mctx.arc(world.exit.x*sx,world.exit.y*sy,3,0,7);mctx.fill();mctx.fillStyle='#4de2c1';mctx.beginPath();mctx.arc(player.x*sx,player.y*sy,3,0,7);mctx.fill()}
function tick(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;gameTime+=dt;if(!paused&&!runOver){move(dt);if(Math.floor(gameTime*5)!==Math.floor((gameTime-dt)*5))renderUI()}draw();requestAnimationFrame(tick)}
function openBase(){renderUI();document.getElementById('baseOverlay').classList.add('open');paused=true}
function buyUpgrade(key){let u=upgradeData.find(v=>v.key===key);if(!u)return;let level=profile.upgrades[key],cost=u.base*(level+1);if(level>=u.max||profile.credits<cost)return;profile.credits-=cost;profile.upgrades[key]++;save();renderUI();toast(`${u.name} INSTALLED · READY FOR NEXT DESCENT`)}
