document.getElementById('continueBtn').addEventListener('click',()=>{document.getElementById('resultOverlay').classList.remove('open');generate();renderUI()});document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>{let id=b.dataset.close;document.getElementById(id).classList.remove('open');if(id==='baseOverlay')paused=runOver}));
