const joy=document.getElementById('joy'),knob=document.getElementById('joyKnob');function joyMove(e){let r=joy.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=r.width*.36,d=Math.hypot(dx,dy);if(d>max){dx*=max/d;dy*=max/d}joystick.x=dx/max;joystick.y=dy/max;knob.style.transform=`translate(${dx}px,${dy}px)`}joy.addEventListener('pointerdown',e=>{e.preventDefault();joystick.active=true;joy.setPointerCapture(e.pointerId);joyMove(e)});joy.addEventListener('pointermove',e=>{if(joystick.active)joyMove(e)});function joyEnd(){joystick.active=false;joystick.x=joystick.y=0;knob.style.transform='translate(0,0)'}joy.addEventListener('pointerup',joyEnd);joy.addEventListener('pointercancel',joyEnd);
for(const overlay of document.querySelectorAll('.overlay'))overlay.addEventListener('click',e=>{if(e.target===overlay&&overlay.id==='baseOverlay'){overlay.classList.remove('open');paused=runOver}});
generate();renderUI();requestAnimationFrame(tick);
